// Improved application with enhanced error handling and security
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

// Initialize express app
const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security

// Rate limiting to prevent DDoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Global rate limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: 'Too many requests from this IP on this endpoint.',
});

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request logging middleware
app.use((req, res, next) => {
  const requestId = req.id || Math.random().toString(36).substring(7);
  req.id = requestId;
  res.setHeader('X-Request-ID', requestId);

  console.log(`[${requestId}] ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// Utility function for handling validation errors
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      errors: errors.array().map(err => ({
        field: err.path || err.param,
        message: err.msg,
        value: err.value
      }))
    });
  }
  next();
};

// Async wrapper to catch errors in async route handlers
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Global error handling middleware
app.use((err, req, res, next) => {
  // Log the error with request ID for tracing
  console.error(`[${req.id}] Error:`, {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    status: err.status || 500
  });

  // Don't leak stack traces in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    success: false,
    message: err.message || 'Internal server error',
    requestId: req.id,
    ...(isDevelopment && { stack: err.stack })
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    success: false,
    message: 'Endpoint not found',
    requestId: req.id
  });
});

// HEALTH CHECK ENDPOINT
app.get('/health', (req, res) => {
  try {
    res.json({
      success: true,
      data: {
        status: 'ok',
        timestamp: new Date().toISOString()
      }
    });
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// USERS ENDPOINT - with query validation
app.get(
  '/users',
  [
    // Validate and sanitize query parameters
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be an integer between 1 and 100')
      .toInt(),
    query('page')
      .optional()
      .isInt({ min: 1 })
      .withMessage('Page must be a positive integer')
      .toInt(),
    query('sort')
      .optional()
      .isIn(['id', 'name', 'email'])
      .withMessage('Sort must be one of: id, name, email'),
    query('order')
      .optional()
      .isIn(['asc', 'desc'])
      .withMessage('Order must be either asc or desc')
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const { limit = 10, page = 1, sort = 'id', order = 'asc' } = req.query;

    // Simulated user data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    // Sort users
    const sortedUsers = [...allUsers].sort((a, b) => {
      const aVal = a[sort];
      const bVal = b[sort];

      if (typeof aVal === 'string') {
        return order === 'asc' 
          ? aVal.localeCompare(bVal)
          : bVal.localeCompare(aVal);
      }
      return order === 'asc' ? aVal - bVal : bVal - aVal;
    });

    // Paginate users
    const startIndex = (page - 1) * limit;
    const paginatedUsers = sortedUsers.slice(startIndex, startIndex + limit);

    res.json({
      success: true,
      data: {
        users: paginatedUsers,
        pagination: {
          page,
          limit,
          total: allUsers.length,
          totalPages: Math.ceil(allUsers.length / limit)
        }
      }
    });
  })
);

// USER BY ID ENDPOINT - with parameter validation
app.get(
  '/users/:id',
  [
    // Validate and sanitize route parameter
    param('id')
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer')
      .toInt()
  ],
  handleValidationErrors,
  asyncHandler(async (req, res, next) => {
    const { id } = req.params;

    // Simulated user data
    const users = {
      1: { id: 1, name: 'Alice', email: 'alice@example.com' },
      2: { id: 2, name: 'Bob', email: 'bob@example.com' },
      3: { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    };

    const user = users[id];

    if (!user) {
      const error = new Error(`User with ID ${id} not found`);
      error.status = 404;
      throw error;
    }

    res.json({
      success: true,
      data: user
    });
  })
);

// CREATE USER ENDPOINT - with body validation
app.post(
  '/users',
  strictLimiter,
  [
    // Validate request body
    body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .isLength({ min: 2, max: 100 })
      .withMessage('Name must be between 2 and 100 characters')
      .escape(), // Escape HTML entities to prevent XSS

    body('email')
      .trim()
      .notEmpty()
      .withMessage('Email is required')
      .isEmail()
      .withMessage('Must be a valid email address')
      .normalizeEmail(), // Normalize email format

    body('age')
      .optional()
      .isInt({ min: 0, max: 150 })
      .withMessage('Age must be between 0 and 150')
      .toInt()
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const { name, email, age } = req.body;

    // Simulate user creation
    const newUser = {
      id: Date.now(), // In production, use proper ID generation
      name,
      email,
      age: age || null,
      createdAt: new Date().toISOString()
    };

    // In production, save to database here
    // await db.users.create(newUser);

    res.status(201).json({
      success: true,
      data: newUser
    });
  })
);

// Start server only if not being imported for testing
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });
}

module.exports = app;

# Security Review Report: app.js

## Executive Summary

The current `app.js` implementation lacks essential security controls, error handling, and input validation. This report outlines identified vulnerabilities and provides concrete recommendations to secure the application.

## Identified Vulnerabilities

### 1. No Input Validation [CRITICAL]
**Risk:** Injection attacks, data corruption, unexpected behavior

**Current State:**
```javascript
app.get('/users', (req, res) => {
  // No validation of query parameters
  res.json([...]);
});
```

**Impact:**
- SQL injection vulnerabilities (if database is added)
- NoSQL injection vulnerabilities
- Potential for malicious data manipulation

---

### 2. No Error Handling [HIGH]
**Risk:** Information disclosure, application crashes

**Current State:**
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
// No error handling middleware
```

**Impact:**
- Unhandled exceptions crash the server
- Stack traces may leak sensitive information
- Poor user experience

---

### 3. Missing Security Headers [HIGH]
**Risk:** Various attacks (XSS, clickjacking, etc.)

**Current State:**
```javascript
const app = express();
// No security middleware
```

**Missing Headers:**
- `Content-Security-Policy`
- `X-Frame-Options`
- `X-Content-Type-Options`
- `Strict-Transport-Security`
- `X-XSS-Protection`

---

### 4. No Rate Limiting [MEDIUM]
**Risk:** DDoS attacks, brute force attacks

**Impact:**
- API can be easily overwhelmed
- No protection against automated attacks
- Resource exhaustion

---

### 5. No Request Size Limits [MEDIUM]
**Risk:** DDoS through large payloads

**Impact:**
- Memory exhaustion attacks
- Slowloris attacks
- Server crashes

---

### 6. No Logging [MEDIUM]
**Risk:** Inability to detect or investigate attacks

**Impact:**
- No audit trail
- Difficult to troubleshoot issues
- No security monitoring

---

## Detailed Recommendations

### 1. Input Validation

#### Query Parameter Validation
```javascript
app.get('/users', 
  [
    query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    query('page').optional().isInt({ min: 1 }).toInt(),
    query('sort').optional().isIn(['id', 'name', 'email'])
  ],
  handleValidationErrors,
  (req, res) => { /* handler */ }
);
```

#### Route Parameter Validation
```javascript
app.get('/users/:id',
  [
    param('id').isInt({ min: 1 }).toInt()
  ],
  handleValidationErrors,
  (req, res) => { /* handler */ }
);
```

#### Request Body Validation
```javascript
app.post('/users',
  [
    body('name').trim().notEmpty().isLength({ min: 2, max: 100 }).escape(),
    body('email').trim().isEmail().normalizeEmail(),
    body('age').optional().isInt({ min: 0, max: 150 })
  ],
  handleValidationErrors,
  (req, res) => { /* handler */ }
);
```

#### Validation Error Handler
```javascript
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      errors: errors.array()
    });
  }
  next();
};
```

### 2. Error Handling

#### Global Error Handler
```javascript
app.use((err, req, res, next) => {
  console.error(`[${req.id}] Error:`, err.message);

  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    success: false,
    message: isDevelopment ? err.message : 'Internal server error',
    requestId: req.id,
    ...(isDevelopment && { stack: err.stack })
  });
});
```

#### Async Route Wrapper
```javascript
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};
```

#### 404 Handler
```javascript
app.use((req, res) => {
  res.status(404).json({
    success: false,
    message: 'Endpoint not found',
    requestId: req.id
  });
});
```

### 3. Security Headers

Use Helmet to automatically set security headers:
```javascript
const helmet = require('helmet');
app.use(helmet());

// Or configure manually
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", "data:"],
  }
}));
```

### 4. Rate Limiting

```javascript
const rateLimit = require('express-rate-limit');

// General rate limit
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window
  message: 'Too many requests, please try again later.'
});
app.use(limiter);

// Strict rate limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10, // Only 10 requests
});
app.use('/api/auth', strictLimiter);
```

### 5. Request Size Limits

```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
```

### 6. Request Logging & Tracing

```javascript
app.use((req, res, next) => {
  const requestId = crypto.randomUUID();
  req.id = requestId;
  res.setHeader('X-Request-ID', requestId);

  console.log(`[${requestId}] ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});
```

### 7. Additional Security Measures

#### CORS Configuration
```javascript
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));
```

#### Sanitization
```javascript
const { sanitize } = require('express-validator');
// Always sanitize user input
body('input').trim().escape();
```

#### Environment Variables
```javascript
// Use .env for sensitive configuration
require('dotenv').config();

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
```

## Required Dependencies

```json
{
  "dependencies": {
    "express": "^4.18.0",
    "helmet": "^7.0.0",
    "express-rate-limit": "^6.7.0",
    "express-validator": "^7.0.0",
    "cors": "^2.8.5",
    "dotenv": "^16.0.0"
  }
}
```

Install with:
```bash
npm install express helmet express-rate-limit express-validator cors dotenv
```

## Security Checklist

- [x] Input validation on all endpoints
- [x] Request body size limits
- [x] Global error handling
- [x] Security headers (Helmet)
- [x] Rate limiting
- [x] Request logging with unique IDs
- [ ] CORS configuration
- [ ] HTTPS/TLS enforcement
- [ ] Authentication & Authorization
- [ ] Input sanitization against XSS
- [ ] SQL/NoSQL injection prevention
- [ ] File upload validation (if applicable)
- [ ] API key/header authentication
- [ ] Session management
- [ ] CSRF protection
- [ ] Dependency vulnerability scanning

## Best Practices

1. **Defense in Depth**: Implement multiple layers of security
2. **Fail Securely**: Default to deny, not allow
3. **Principle of Least Privilege**: Minimum required access
4. **Keep Dependencies Updated**: Regular security patches
5. **Monitor and Audit**: Log security-relevant events
6. **Use Security Linters**: ESLint security plugins
7. **Implement Content Security Policy**: Prevent XSS
8. **Regular Security Audits**: Penetration testing, code reviews

## Testing Recommendations

1. **Unit Tests**: Validate all validation rules
2. **Integration Tests**: Test error handling flows
3. **Security Tests**: SQL injection, XSS, DDoS
4. **Load Testing**: Verify rate limiting works
5. **Fuzz Testing**: Test with malformed inputs

```bash
# Install testing dependencies
npm install --save-dev jest supertest nock
```

Example security test:
```javascript
describe('Security Tests', () => {
  it('should reject malicious input', async () => {
    const response = await request(app)
      .get('/users?limit=<script>alert(1)</script>')
      .expect(400);
    expect(response.body.errors).toBeDefined();
  });

  it('should enforce rate limiting', async () => {
    const requests = Array(105).fill(null).map(() => 
      request(app).get('/users')
    );
    const responses = await Promise.all(requests);
    const rateLimited = responses.filter(r => r.status === 429);
    expect(rateLimited.length).toBeGreaterThan(0);
  });
});
```

## Conclusion

The current `app.js` requires significant security enhancements before it should be used in production. The `app-improved.js` file provides a comprehensive implementation of these recommendations. Always conduct a security audit before deploying to production.

## Additional Resources

- [OWASP Node.js Security Cheat Sheet](https://cheatsheetseries.owasp.org/cheatsheets/NodeJS_Security_Cheat_Sheet.html)
- [Express Security Best Practices](https://expressjs.com/en/advanced/best-practice-security.html)
- [Helmet Documentation](https://helmetjs.github.io/)
- [Express Validator Documentation](https://express-validator.github.io/)

