const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  message: { error: 'Rate limit exceeded for this endpoint.' }
});

// Body size limits to prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Prevent parameter pollution
app.set('query parser', 'extended');

// Custom error handler middleware
function errorHandler(err, req, res, next) {
  // Log error for debugging (in production, use proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    timestamp: new Date().toISOString()
  });

  // Don't leak error details in production
  const isDev = process.env.NODE_ENV === 'development';

  if (err.type === 'entity.parse.failed') {
    return res.status(400).json({ 
      error: 'Invalid JSON format' 
    });
  }

  if (err.type === 'entity.too.large') {
    return res.status(413).json({ 
      error: 'Request body too large' 
    });
  }

  // Default error response
  res.status(err.status || 500).json({
    error: isDev ? err.message : 'Internal server error',
    ...(isDev && { stack: err.stack })
  });
}

// Validation middleware
function validateRequest(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg
      }))
    });
  }
  next();
}

// Sanitization helper (example for XSS prevention)
function sanitizeString(value) {
  if (typeof value !== 'string') return value;
  return value
    .replace(/[<>]/g, '')
    .trim()
    .substring(0, 1000); // Prevent extremely long strings
}

// Health endpoint - simplified for production
app.get('/health', (req, res) => {
  // In production, don't expose detailed system information
  res.json({ 
    status: 'ok',
    timestamp: new Date().toISOString()
  });
});

// Users endpoint with query parameter validation
app.get('/users', 
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer')
      .toInt(),
    query('search')
      .optional()
      .isString()
      .isLength({ max: 100 })
      .withMessage('Search term must be at most 100 characters')
      .trim()
  ],
  validateRequest,
  strictLimiter,
  (req, res) => {
    try {
      const { limit = 10, offset = 0, search } = req.query;

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply search filter if provided
      let filteredUsers = users;
      if (search) {
        const sanitizedSearch = sanitizeString(search);
        filteredUsers = users.filter(user => 
          user.name.toLowerCase().includes(sanitizedSearch.toLowerCase()) ||
          user.email.toLowerCase().includes(sanitizedSearch.toLowerCase())
        );
      }

      // Apply pagination
      const paginatedUsers = filteredUsers.slice(offset, offset + limit);

      res.json({
        data: paginatedUsers,
        meta: {
          total: filteredUsers.length,
          limit,
          offset
        }
      });

    } catch (error) {
      // Forward to error handler
      next(error);
    }
  }
);

// Example: POST endpoint with comprehensive validation
app.post('/users',
  [
    body('name')
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .matches(/^[a-zA-Z\s'-]+$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .isEmail()
      .normalizeEmail()
      .withMessage('Invalid email format')
      .isLength({ max: 255 })
      .withMessage('Email too long'),
    body('age')
      .optional()
      .isInt({ min: 0, max: 150 })
      .withMessage('Age must be between 0 and 150')
  ],
  validateRequest,
  strictLimiter,
  (req, res) => {
    try {
      const { name, email, age } = req.body;

      // Sanitize inputs
      const sanitizedName = sanitizeString(name);

      // In a real application, save to database here
      const newUser = {
        id: Date.now(), // In production, use proper ID generation
        name: sanitizedName,
        email: email.toLowerCase(),
        ...(age && { age })
      };

      res.status(201).json(newUser);

    } catch (error) {
      next(error);
    }
  }
);

// 404 handler - must be after all routes
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    path: req.path
  });
});

// Error handler - must be last
app.use(errorHandler);

const PORT = process.env.PORT || 3000;

// Only start server if not in test mode
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });
}

module.exports = app;

