const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet());

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Request logging middleware
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// Validation middleware helper
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};

// Healthcheck endpoint - generally safe to keep open
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Users endpoint with validation and security
app.get('/users', [
  // Validate query parameters
  query('id')
    .optional()
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer')
    .toInt(),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),
  query('email')
    .optional()
    .isEmail()
    .withMessage('Email must be valid')
    .normalizeEmail(),
], handleValidationErrors, (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply filters based on validated query params
    let filteredUsers = users;

    if (req.query.id) {
      filteredUsers = filteredUsers.filter(u => u.id === req.query.id);
    }

    if (req.query.email) {
      filteredUsers = filteredUsers.filter(u => u.email === req.query.email);
    }

    if (req.query.limit) {
      filteredUsers = filteredUsers.slice(0, req.query.limit);
    }

    // Filter out sensitive fields if needed
    const safeUsers = filteredUsers.map(({ id, name }) => ({ id, name }));

    res.json(safeUsers);
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'An error occurred while retrieving users'
    });
  }
});

// Example: POST endpoint for creating users (demonstrates input validation)
app.post('/users', [
  // Validate and sanitize input
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .escape(), // Escape HTML entities
  body('email')
    .trim()
    .isEmail()
    .withMessage('Valid email is required')
    .normalizeEmail()
    .isLength({ max: 255 })
    .withMessage('Email is too long'),
], handleValidationErrors, (req, res) => {
  try {
    // Process validated user data
    const { name, email } = req.body;

    // In a real app, you would save to database here
    const newUser = {
      id: Date.now(), // Simple ID generation - use UUID in production
      name,
      email
    };

    console.log('User created:', { id: newUser.id, email: newUser.email });

    res.status(201).json({
      message: 'User created successfully',
      user: { id: newUser.id, name: newUser.name } // Don't return sensitive data
    });
  } catch (error) {
    console.error('User creation error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'An error occurred while creating the user'
    });
  }
});

// Example: User by ID endpoint with parameter validation
app.get('/users/:id', [
  param('id')
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer')
    .toInt(),
], handleValidationErrors, (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === req.params.id);

    if (!user) {
      return res.status(404).json({
        error: 'Not found',
        message: 'User not found'
      });
    }

    // Return only safe fields
    res.json({ id: user.id, name: user.name });
  } catch (error) {
    console.error('User lookup error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'An error occurred while retrieving the user'
    });
  }
});

// 404 handler - must be after all other routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: 'The requested resource was not found'
  });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: 'Internal server error',
    ...(isDevelopment && { details: err.message, stack: err.stack })
  });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

