const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult, param } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP security headers
app.use(express.json({ limit: '10kb' })); // Limit request body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(limiter);

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10, // Only 10 requests per 15 minutes
  message: 'Too many requests to this endpoint, please try again later.',
});

// Validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
      })),
    });
  }
  next();
};

// Centralized error handler
const errorHandler = (err, req, res, next) => {
  // Log error securely (in production, use a proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
  });

  // Don't expose sensitive error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack }),
  });
};

// Request logging middleware
const requestLogger = (req, res, next) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log({
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      timestamp: new Date().toISOString(),
    });
  });

  next();
};

app.use(requestLogger);

// Utility function to safely send JSON responses
const safeJsonResponse = (res, data, statusCode = 200) => {
  try {
    res.status(statusCode).json(data);
  } catch (error) {
    console.error('JSON serialization error:', error);
    res.status(500).json({ error: 'Failed to serialize response data' });
  }
};

// Health check endpoint
app.get('/health', (req, res) => {
  safeJsonResponse(res, {
    status: 'ok',
    timestamp: new Date().toISOString(),
  });
});

// Users endpoint with query parameter validation
app.get('/users', 
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be an integer between 1 and 100'),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer'),
    query('sort')
      .optional()
      .matches(/^(id|name|email):(asc|desc)$/)
      .withMessage('Sort must be in format "field:direction" (e.g., "name:asc")'),
  ],
  validateRequest,
  (req, res) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Sanitize and apply query parameters safely
      const limit = parseInt(req.query.limit) || 100;
      const offset = parseInt(req.query.offset) || 0;

      // Apply filtering (sensitive data filtering example)
      const sanitizedUsers = users.map(user => ({
        ...user,
        // Remove any sensitive fields if needed
        // updatedAt: undefined, // Example of field filtering
      }));

      safeJsonResponse(res, sanitizedUsers.slice(offset, offset + limit));
    } catch (error) {
      next(error);
    }
  }
);

// New endpoint: Get user by ID with path parameter validation
app.get('/users/:id',
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer'),
  ],
  validateRequest,
  strictLimiter, // Apply stricter rate limiting
  (req, res, next) => {
    try {
      const userId = parseInt(req.params.id);
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({
          error: 'User not found',
        });
      }

      safeJsonResponse(res, user);
    } catch (error) {
      next(error);
    }
  }
);

// Example: User creation endpoint with body validation
app.post('/users',
  [
    body('name')
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .escape(), // Escape HTML entities to prevent XSS
    body('email')
      .trim()
      .isEmail()
      .withMessage('Must be a valid email address')
      .normalizeEmail(), // Normalize email format
    body('age')
      .optional()
      .isInt({ min: 0, max: 150 })
      .withMessage('Age must be between 0 and 150'),
  ],
  validateRequest,
  strictLimiter,
  (req, res, next) => {
    try {
      // In a real application, you would save to a database here
      const newUser = {
        id: Date.now(), // Simple ID generation (use proper IDs in production)
        name: req.body.name,
        email: req.body.email,
        ...(req.body.age && { age: req.body.age }),
      };

      safeJsonResponse(res, newUser, 201);
    } catch (error) {
      next(error);
    }
  }
);

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.method} ${req.path} not found`,
  });
});

// Global error handler (must be last)
app.use(errorHandler);

// Server startup with environment validation
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Validate required environment variables
const requiredEnvVars = [];
const missingEnvVars = requiredEnvVars.filter(envVar => !process.env[envVar]);

if (missingEnvVars.length > 0) {
  console.error(`Missing required environment variables: ${missingEnvVars.join(', ')}`);
  process.exit(1);
}

// Graceful shutdown handling
const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle graceful shutdown
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close((err) => {
    if (err) {
      console.error('Error closing server:', err);
      process.exit(1);
    }

    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  gracefulShutdown('uncaughtException');
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  gracefulShutdown('unhandledRejection');
});

module.exports = { app, server };

