    .trim()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be a positive integer between 1 and 100')
    .toInt(),
  query('sort')
    .optional()
    .trim()
    .isIn(['id', 'name', 'email'])
    .withMessage('Sort must be one of: id, name, email'),
  handleValidationErrors,
];

/**
