/**
 * Secure Express Application with Error Handling and Input Validation
 * Security Best Practices Implemented:
 * - Request validation and sanitization
 * - Rate limiting
 * - Security headers (Helmet)
 * - CORS configuration
 * - Proper error handling
 * - Input sanitization
 * - Logging
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');
const cors = require('cors');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// CORS configuration - Adjust origin whitelist as needed
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
}));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
  // Skip rate limiting for trusted IPs if needed
  skip: (req) => {
    return req.ip === '127.0.0.1' || req.ip === '::1';
  }
});

// Apply rate limiting to all routes
app.use(limiter);

// Stricter rate limiting for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 attempts per 15 minutes
  message: {
    error: 'Too many authentication attempts, please try again later.'
  },
  skipFailedRequests: true
});

// Body parser with size limits to prevent payload overflow attacks
app.use(express.json({ 
  limit: '10kb', // Small limit for security
  strict: true 
}));

app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// ============================================================================
// VALIDATION MIDDLEWARE
// ============================================================================

/**
 * Middleware to check validation results
 * If validation fails, returns 400 with error details
 */
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);

  if (!errors.isEmpty()) {
    // Log validation failures for security monitoring
    console.warn(`Validation failed for ${req.method} ${req.path}:`, {
      ip: req.ip,
      userAgent: req.get('user-agent'),
      errors: errors.array()
    });

    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
        value: err.value // Be careful not to expose sensitive data
      }))
    });
  }

  next();
};

/**
 * Sanitization helper for user input
 */
const sanitizeInput = (input) => {
  if (typeof input === 'string') {
    return input.trim().replace(/[<>]/g, '');
  }
  return input;
};

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * 404 Not Found Handler
 */
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found on this server.',
    path: req.path
  });
});

/**
 * Global Error Handler
 * Must be defined after all other middleware/routes
 */
app.use((err, req, res, next) => {
  // Log the error for debugging
  console.error('Error occurred:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.url,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  // Handle specific error types
  if (err.type === 'entity.parse.failed') {
    return res.status(400).json({
      error: 'Invalid JSON'
    });
  }

  if (err.type === 'entity.too.large') {
    return res.status(413).json({
      error: 'Request entity too large'
    });
  }

  // Default error response
  const statusCode = err.statusCode || 500;
  const response = {
    error: isDevelopment ? err.message : 'Internal Server Error',
    timestamp: new Date().toISOString()
  };

  // Add stack trace only in development
  if (isDevelopment) {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

// ============================================================================
// ASYNC ROUTE WRAPPER
// ============================================================================

/**
 * Wrapper for async route handlers to catch errors
 * Eliminates need for try-catch in every route
 */
const asyncHandler = (fn) => {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint
 * Returns system status without sensitive information
 */
app.get('/health', asyncHandler(async (req, res) => {
  // You could add actual health checks here (database, cache, etc.)
  const healthStatus = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  };

  res.json(healthStatus);
}));

/**
 * Get users endpoint with pagination and field filtering
 */
app.get('/users', [
  // Validate query parameters
  query('page')
    .optional()
    .isInt({ min: 1 })
    .withMessage('Page must be a positive integer')
    .toInt(),

  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),

  query('fields')
    .optional()
    .custom((value) => {
      // Validate that fields contains only allowed field names
      const allowedFields = ['id', 'name', 'email'];
      const requestedFields = value.split(',').map(f => f.trim());
      const invalidFields = requestedFields.filter(f => !allowedFields.includes(f));

      if (invalidFields.length > 0) {
        throw new Error(`Invalid fields: ${invalidFields.join(', ')}`);
      }
      return true;
    }),

  validateRequest
], asyncHandler(async (req, res) => {
  // In a real application, fetch from database
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const page = req.query.page || 1;
  const limit = req.query.limit || 10;
  const fields = req.query.fields;

  // Apply field filtering if requested
  let response = users;
  if (fields) {
    const fieldList = fields.split(',').map(f => f.trim());
    response = users.map(user => {
      const filtered = {};
      fieldList.forEach(field => {
        if (user.hasOwnProperty(field)) {
          filtered[field] = user[field];
        }
      });
      return filtered;
    });
  }

  // Sanitize output
  response = response.map(user => ({
    ...user,
    name: sanitizeInput(user.name),
    email: sanitizeInput(user.email).toLowerCase()
  }));

  res.json({
    data: response,
    pagination: {
      page,
      limit,
      total: users.length,
      totalPages: Math.ceil(users.length / limit)
    }
  });
}));

/**
 * Example: Create user endpoint with validation
 */
app.post('/users', authLimiter, [
  // Validate request body
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/)
    .withMessage('Name can only contain letters, spaces, hyphens, and apostrophes')
    .escape(), // Sanitize HTML entities

  body('email')
    .trim()
    .isEmail()
    .withMessage('Must be a valid email address')
    .normalizeEmail()
    .isLength({ max: 255 })
    .withMessage('Email is too long'),

  validateRequest
], asyncHandler(async (req, res) => {
  const { name, email } = req.body;

  // TODO: Check for duplicate email in database
  // TODO: Hash sensitive data before storing
  // TODO: Validate against user creation business rules

  // Simulated user creation
  const newUser = {
    id: Date.now(), // In production, use proper ID generation
    name: sanitizeInput(name),
    email: sanitizeInput(email).toLowerCase(),
    createdAt: new Date().toISOString()
  };

  // Log user creation (without sensitive data)
  console.info(`User created: ${newUser.id}`);

  res.status(201).json({
    message: 'User created successfully',
    data: {
      id: newUser.id,
      name: newUser.name
      // Don't return sensitive information in response
    }
  });
}));

/**
 * Example: Get user by ID with parameter validation
 */
app.get('/users/:id', [
  param('id')
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer')
    .toInt(),

  validateRequest
], asyncHandler(async (req, res) => {
  const userId = req.params.id;

  // In a real application, fetch from database
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const user = users.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({
      error: 'User not found',
      message: `No user found with ID: ${userId}`
    });
  }

  // Return sanitized user data
  res.json({
    data: {
      id: user.id,
      name: sanitizeInput(user.name),
      // Consider whether to return email based on authorization
      email: sanitizeInput(user.email).toLowerCase()
    }
  });
}));

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`Security: Helmet enabled, rate limiting active`);
});

// Graceful shutdown handling
const shutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  shutdown('uncaughtException');
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  shutdown('unhandledRejection');
});

module.exports = app;

