/**
 * Security Tests for the Improved Express Application
 * 
 * This file contains examples of how to test various security features.
 * You can run these tests using a testing framework like Jest, Mocha, or manually with curl.
 */

const { describe, test, expect } = require('@jest/globals');
const request = require('supertest');
const app = require('./app.improved.js');

// ============================================================================
// Manual Testing with curl
// ============================================================================

/*
curl COMMANDS FOR MANUAL TESTING:

# 1. Test Security Headers
curl -I http://localhost:3000/health
# Expected headers: X-Content-Type-Options, X-Frame-Options, X-XSS-Protection, etc.

# 2. Test Rate Limiting
for i in {1..105}; do curl -s http://localhost:3000/health; done
# First 100 should succeed, next 5 should return 429

# 3. Test Input Validation - Invalid Email
curl -X POST http://localhost:3000/users \
  -H "Content-Type: application/json" \
  -d '{"name":"Alice","email":"not-an-email"}'
# Expected: 400 with validation error

# 4. Test Input Validation - Invalid Name (Too Short)
curl -X POST http://localhost:3000/users \
  -H "Content-Type: application/json" \
  -d '{"name":"A","email":"alice@example.com"}'
# Expected: 400 with validation error

# 5. Test Input Sanitization - XSS Attempt
curl -X POST http://localhost:3000/users \
  -H "Content-Type: application/json" \
  -d '{"name":"<script>alert(1)</script>","email":"attacker@example.com"}'
# Expected: 201 with sanitized name (script tags removed)

# 6. Test Query Parameter Validation - Invalid Page
curl http://localhost:3000/users?page=-5
# Expected: 400 with validation error

# 7. Test Query Parameter Validation - Invalid Limit
curl http://localhost:3000/users?limit=500
# Expected: 400 with validation error (max is 100)

# 8. Test Query Parameter Validation - Invalid Sort
curl http://localhost:3000/users?sort=malicious_column
# Expected: 400 with validation error

# 9. Test Route Parameter Validation - Invalid ID
curl http://localhost:3000/users/not-a-number
# Expected: 400 with validation error

# 10. Test 404 Handling
curl http://localhost:3000/nonexistent-endpoint
# Expected: 404 with proper error message

# 11. Test Too Large Payload
curl -X POST http://localhost:3000/users \
  -H "Content-Type: application/json" \
  -d '{"name":"'$(python3 -c 'print("A"*20000)')'","email":"test@test.com"}'
# Expected: 413 Payload Too Large

# 12. Test Invalid JSON
curl -X POST http://localhost:3000/users \
  -H "Content-Type: application/json" \
  -d '{"name":"Alice","email":"invalid"'

# 13. Test ENUM Validation
curl http://localhost:3000/health?format=not-valid
# Expected: 400 with validation error
*/

// ============================================================================
// Automated Tests with Jest
// ============================================================================

describe('Security Tests', () => {

  // Test 1: Security Headers
  describe('Security Headers', () => {
    test('should set X-Content-Type-Options header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['x-content-type-options']).toBe('nosniff');
    });

    test('should set X-Frame-Options header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['x-frame-options']).toBe('DENY');
    });

    test('should set X-XSS-Protection header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['x-xss-protection']).toBeDefined();
    });

    test('should set Strict-Transport-Security header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['strict-transport-security']).toBeDefined();
    });
  });

  // Test 2: Rate Limiting
  describe('Rate Limiting', () => {
    test('should allow requests within limit', async () => {
      const response = await request(app).get('/health');
      expect(response.status).toBe(200);
    });

    test.skip('should block requests exceeding rate limit', async () => {
      // This test is skipped because it would make 100+ requests
      // Uncomment to test rate limiting (takes time)
      const promises = Array(105).fill().map(() => 
        request(app).get('/health')
      );

      const responses = await Promise.all(promises);
      const rateLimitedResponses = responses.filter(r => r.status === 429);

      expect(rateLimitedResponses.length).toBeGreaterThan(0);
      expect(rateLimitedResponses[0].body).toHaveProperty('error');
    });
  });

  // Test 3: Input Validation - Query Parameters
  describe('Query Parameter Validation', () => {
    test('should reject invalid page number', async () => {
      const response = await request(app).get('/users?page=-1');
      expect(response.status).toBe(400);
      expect(response.body).toHaveProperty('error');
      expect(response.body.details[0].field).toBe('page');
    });

    test('should reject non-numeric page', async () => {
      const response = await request(app).get('/users?page=abc');
      expect(response.status).toBe(400);
    });

    test('should reject limit exceeding maximum', async () => {
      const response = await request(app).get('/users?limit=500');
      expect(response.status).toBe(400);
      expect(response.body.details[0].field).toBe('limit');
    });

    test('should reject invalid sort parameter', async () => {
      const response = await request(app).get('/users?sort=malicious_column');
      expect(response.status).toBe(400);
      expect(response.body.details[0].field).toBe('sort');
    });

    test('should accept valid query parameters', async () => {
      const response = await request(app).get('/users?page=1&limit=10&sort=name');
      expect(response.status).toBe(200);
      expect(response.body).toHaveProperty('data');
      expect(response.body).toHaveProperty('pagination');
    });
  });

  // Test 4: Input Validation - POST Body
  describe('POST Body Validation', () => {
    test('should reject invalid email', async () => {
      const response = await request(app)
        .post('/users')
        .send({ name: 'Alice', email: 'not-an-email' });

      expect(response.status).toBe(400);
      expect(response.body.details[0].field).toBe('email');
    });

    test('should reject name that is too short', async () => {
      const response = await request(app)
        .post('/users')
        .send({ name: 'A', email: 'alice@example.com' });

      expect(response.status).toBe(400);
      expect(response.body.details[0].field).toBe('name');
    });

    test('should reject name that is too long', async () => {
      const response = await request(app)
        .post('/users')
        .send({ name: 'A'.repeat(51), email: 'alice@example.com' });

      expect(response.status).toBe(400);
    });

    test('should reject name with invalid characters', async () => {
      const response = await request(app)
        .post('/users')
        .send({ name: 'Alice<script>alert(1)</script>', email: 'alice@example.com' });

      // The script tags should be removed by sanitization
      // But validator still catches it before sanitization
      expect(response.body.data?.name).not.toContain('<script>');
    });

    test('should accept valid user data', async () => {
      const response = await request(app)
        .post('/users')
        .send({ name: 'Alice Johnson', email: 'alice@example.com' });

      expect(response.status).toBe(201);
      expect(response.body).toHaveProperty('message');
      expect(response.body.data).toHaveProperty('id');
      expect(response.body.data.name).toBe('Alice Johnson');
    });
  });

  // Test 5: Route Parameter Validation
  describe('Route Parameter Validation', () => {
    test('should reject non-numeric user ID', async () => {
      const response = await request(app).get('/users/abc');
      expect(response.status).toBe(400);
      expect(response.body.details[0].field).toBe('id');
    });

    test('should reject negative user ID', async () => {
      const response = await request(app).get('/users/-1');
      expect(response.status).toBe(400);
    });

    test('should return 404 for non-existent user', async () => {
      const response = await request(app).get('/users/99999');
      expect(response.status).toBe(404);
      expect(response.body.error).toBe('Not found');
    });

    test('should return user data for valid ID', async () => {
      const response = await request(app).get('/users/1');
      expect(response.status).toBe(200);
      expect(response.body.data).toHaveProperty('id');
      expect(response.body.data).toHaveProperty('name');
      expect(response.body.data).toHaveProperty('email');
    });
  });

  // Test 6: 404 Handling
  describe('404 Handling', () => {
    test('should return 404 for non-existent routes', async () => {
      const response = await request(app).get('/nonexistent');
      expect(response.status).toBe(404);
      expect(response.body).toHaveProperty('error');
      expect(response.body).toHaveProperty('message');
      expect(response.body).toHaveProperty('timestamp');
    });

    test('should return 404 for invalid methods on valid routes', async () => {
      const response = await request(app).delete('/users/1');
      expect(response.status).toBe(404);
    });
  });

  // Test 7: Input Sanitization
  describe('Input Sanitization', () => {
    test('should sanitize XSS attempts in name', async () => {
      const maliciousName = '<script>alert("XSS")</script>Alice';
      const response = await request(app)
        .post('/users')
        .send({ name: maliciousName, email: 'alice@example.com' });

      expect(response.body.data.name).not.toContain('<script>');
      expect(response.body.data.name).not.toContain('alert');
    });

    test('should trim whitespace', async () => {
      const response = await request(app)
        .post('/users')
        .send({ name: '  Alice  ', email: '  alice@example.com  ' });

      expect(response.body.data.name).toBe('Alice');
      expect(response.body.data.email).toBe('alice@example.com');
    });
  });

  // Test 8: Error Handling
  describe('Error Handling', () => {
    test('should return consistent error format', async () => {
      const response = await request(app).post('/users').send({ name: 'A' });

      expect(response.body).toHaveProperty('error');
      expect(response.body).toHaveProperty('details');
      expect(Array.isArray(response.body.details)).toBe(true);
    });

    test('should not expose stack traces in production', async () => {
      // This test would need NODE_ENV=production
      const response = await request(app).get('/nonexistent');
      expect(response.body).not.toHaveProperty('stack');
    });
  });

  // Test 9: JSON Structure
  describe('Response Structure', () => {
    test('should return proper JSON content-type', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['content-type']).toMatch(/application\/json/);
    });

    test('health endpoint should have required fields', async () => {
      const response = await request(app).get('/health');
      expect(response.body).toHaveProperty('status');
      expect(response.body).toHaveProperty('timestamp');
    });

    test('users endpoint should have pagination', async () => {
      const response = await request(app).get('/users');
      expect(response.body).toHaveProperty('data');
      expect(response.body).toHaveProperty('pagination');
      expect(response.body.pagination).toHaveProperty('page');
      expect(response.body.pagination).toHaveProperty('limit');
      expect(response.body.pagination).toHaveProperty('total');
    });
  });

  // Test 10: Edge Cases
  describe('Edge Cases', () => {
    test('should handle empty request body', async () => {
      const response = await request(app)
        .post('/users')
        .send({});

      expect(response.status).toBe(400);
      expect(response.body.details.length).toBeGreaterThan(0);
    });

    test('should handle missing fields', async () => {
      const response = await request(app)
        .post('/users')
        .send({ name: 'Alice' });

      expect(response.status).toBe(400);
      expect(response.body.details.some(d => d.field === 'email')).toBe(true);
    });

    test('should handle extra fields', async () => {
      const response = await request(app)
        .post('/users')
        .send({ 
          name: 'Alice', 
          email: 'alice@example.com',
          extraField: 'should be ignored'
        });

      expect(response.status).toBe(201);
      expect(response.body.data).not.toHaveProperty('extraField');
    });

    test('should handle SQL injection attempts in name', async () => {
      const sqlInjection = "'; DROP TABLE users; --";
      const response = await request(app)
        .post('/users')
        .send({ name: sqlInjection, email: 'attacker@example.com' });

      // Should handle it gracefully (not crash)
      expect([200, 201, 400, 500]).toContain(response.status);
    });
  });

  // Test 11: Content-Type Handling
  describe('Content-Type Handling', () => {
    test('should require correct content-type for POST', async () => {
      const response = await request(app)
        .post('/users')
        .set('Content-Type', 'text/plain')
        .send('name=Alice&email=alice@example.com');

      // Body parser might handle this, but validation should catch issues
      expect([400, 415]).toContain(response.status);
    });

    test('should handle malformed JSON', async () => {
      const response = await request(app)
        .post('/users')
        .set('Content-Type', 'application/json')
        .send('{ invalid json }');

      expect([400, 500]).toContain(response.status);
    });
  });
});

// ============================================================================
// Security Check Function (can be run independently)
// ============================================================================

async function runSecurityCheck() {
