const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');
// Note: In production, use csurf for CSRF protection

const app = express();

// === Security Middleware ===

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later'
  },
  standardHeaders: true,
  legacyHeaders: false
});

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: {
    error: 'Rate limit exceeded for this endpoint'
  }
});

app.use(limiter);

// Request logging for security monitoring
app.use(morgan('combined'));

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// CORS configuration (adjust origins as needed)
app.use((req, res, next) => {
  const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];
  const origin = req.headers.origin;

  if (allowedOrigins.includes(origin)) {
    res.setHeader('Access-Control-Allow-Origin', origin);
  }

  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  res.setHeader('Access-Control-Allow-Credentials', 'true');
  res.setHeader('Access-Control-Max-Age', '86400');

  if (req.method === 'OPTIONS') {
    return res.sendStatus(204);
  }
  next();
});

// === Input Validation Middleware ===

const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};

// === Sanitization Utilities ===

const sanitizeOutput = (data) => {
  // Remove sensitive fields from output
  const sanitized = { ...data };
  const sensitiveFields = ['password', 'token', 'secret', 'api_key', 'ssn'];

  sensitiveFields.forEach(field => {
    if (sanitized[field]) {
      delete sanitized[field];
    }
  });

  return sanitized;
};

// === Error Handling ===

// Custom error class
class AppError extends Error {
  constructor(message, statusCode = 500, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.timestamp = new Date().toISOString();
    Error.captureStackTrace(this, this.constructor);
  }
}

// 404 handler
app.use((req, res, next) => {
  next(new AppError('Route not found', 404));
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error securely (don't log sensitive data)
  console.error(`[${new Date().toISOString()}] Error:`, {
    message: err.message,
    statusCode: err.statusCode,
    path: req.path,
    method: req.method,
    ip: req.ip,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined
  });

  // Operational errors: safe to reveal to client
  if (err.isOperational) {
    return res.status(err.statusCode).json({
      error: err.message,
      timestamp: err.timestamp,
      ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
    });
  }

  // Programming errors: don't leak details
  res.status(500).json({
    error: 'An unexpected error occurred',
    timestamp: new Date().toISOString(),
    requestId: req.id || 'unknown'
  });
});

// === Routes ===

// Health check endpoint
app.get('/health', [
  query('detailed').optional().isBoolean().withMessage('detailed must be a boolean')
], validateRequest, (req, res) => {
  const { detailed } = req.query;

  const healthData = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  };

  if (detailed === 'true') {
    healthData.memory = process.memoryUsage();
    healthData.nodeVersion = process.version;
  }

  res.json(healthData);
});

// Users endpoint with validation
app.get('/users', [
  query('id').optional().isInt({ min: 1 }).withMessage('ID must be a positive integer'),
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a non-negative integer'),
  query('email').optional().isEmail().withMessage('Email must be valid'),
  query('name').optional().trim().isLength({ min: 1, max: 50 }).withMessage('Name must be 1-50 characters'),
  query('fields').optional().matches(/^[a-zA-Z0-9_,]+$/).withMessage('Fields must contain only alphanumeric characters, commas, and underscores')
], validateRequest, (req, res) => {
  try {
    const { id, limit = 10, offset = 0, email, name, fields } = req.query;

    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user', created_at: '2024-01-01' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin', created_at: '2024-01-02' }
    ];

    // Filter by ID if provided
    let filteredUsers = allUsers;
    if (id) {
      filteredUsers = filteredUsers.filter(user => user.id === parseInt(id));
    }

    // Filter by email if provided
    if (email) {
      filteredUsers = filteredUsers.filter(user => user.email === email);
    }

    // Filter by name if provided (case-insensitive partial match)
    if (name) {
      const nameLower = name.toLowerCase();
      filteredUsers = filteredUsers.filter(user => 
        user.name.toLowerCase().includes(nameLower)
      );
    }

    // Apply pagination
    const totalCount = filteredUsers.length;
    const paginatedUsers = filteredUsers.slice(offset, offset + parseInt(limit));

    // Select specific fields if requested
    let responseUsers = paginatedUsers;
    if (fields) {
      const requestedFields = fields.split(',');
      responseUsers = paginatedUsers.map(user => {
        const selected = {};
        requestedFields.forEach(field => {
          if (user[field] !== undefined) {
            selected[field] = user[field];
          }
        });
        return selected;
      });
    }

    // IMPORTANT: Remove sensitive fields and secure rate limiting headers
    const securedUsers = responseUsers.map(user => sanitizeOutput(user));

    res.json({
      data: securedUsers,
      meta: {
        total: totalCount,
        limit: parseInt(limit),
        offset: parseInt(offset),
        hasMore: offset + parseInt(limit) < totalCount
      }
    });

  } catch (error) {
    throw new AppError('Failed to retrieve users', 500);
  }
});

// === Security: Example of POST endpoint with validation ===

// Example protected endpoint (would also need auth middleware)
app.post('/users', strictLimiter, [
  body('name')
    .trim()
    .isLength({ min: 1, max: 50 })
    .withMessage('Name must be 1-50 characters')
    .matches(/^[a-zA-Z\s'-]+$/)
    .withMessage('Name contains invalid characters')
    .escape(),
  body('email')
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail(),
  body('role')
    .optional()
    .isIn(['user', 'admin', 'moderator'])
    .withMessage('Invalid role')
], validateRequest, (req, res) => {
  try {
    const { name, email, role } = req.body;

    // In production: Check for duplicate email, hash passwords, etc.
    const newUser = {
      id: Date.now(), // Not production-safe ID generation
      name: name,
      email: email,
      role: role || 'user',
      created_at: new Date().toISOString()
    };

    // Sanitize output
    const safeUser = sanitizeOutput(newUser);

    res.status(201).json({
      message: 'User created successfully',
      data: safeUser
    });

  } catch (error) {
    throw new AppError('Failed to create user', 500);
  }
});

// === Server Initialization ===

const PORT = process.env.PORT || 3000;

// Graceful shutdown
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle graceful shutdown
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forcing shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  gracefulShutdown('uncaughtException');
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

module.exports = app;

