/**
 * Improved Express Application with Security Best Practices
 * Includes proper error handling, input validation, and security measures
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const morgan = require('morgan');

// Load environment variables
require('dotenv').config();

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));

// Rate limiting to prevent DoS attacks
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per window
  message: {
    error: 'Too many requests from this IP, please try again later.',
  },
  standardHeaders: true,
  legacyHeaders: false,
});

app.use('/api/', apiLimiter);

// Request logging (skip in tests)
if (NODE_ENV !== 'test') {
  app.use(morgan(NODE_ENV === 'production' ? 'combined' : 'dev'));
}

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================================================
// UTILITY FUNCTIONS
// ============================================================================

/**
 * Wraps async route handlers to catch errors and pass to error middleware
 * @param {Function} fn - Async route handler
 * @returns {Function} Express middleware function
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

/**
 * Validates request using express-validator and returns 400 if invalid
 * @param {Object} req - Express request object
 * @param {Object} res - Express response object
 * @param {Function} next - Express next function
 * @returns {void}
 */
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path || err.param,
        message: err.msg,
        value: err.value,
      })),
    });
  }
  next();
};

/**
 * Sanitizes user object by removing sensitive fields
 * @param {Object} user - User object
 * @returns {Object} Sanitized user object
 */
const sanitizeUser = (user) => {
  const { password, isAdmin, ...sanitized } = user;
  return sanitized;
};

/**
 * Sanitizes HTML entities to prevent XSS
 * @param {string} str - String to sanitize
 * @returns {string} Sanitized string
 */
const escapeHtml = (str) => {
  if (typeof str !== 'string') return str;
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint
 * @route GET /health
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    version: process.env.npm_package_version || '1.0.0',
    environment: NODE_ENV,
  });
});

/**
 * Get users endpoint with pagination and filtering
 * @route GET /users
 * @query {number} limit - Number of users to return (1-100, default: 10)
 * @query {number} page - Page number (default: 1)
 * @query {string} search - Search term for user names
 */
app.get('/users',
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('page')
      .optional()
      .isInt({ min: 1 })
      .withMessage('Page must be a positive integer')
      .toInt(),
    query('search')
      .optional()
      .trim()
      .escape()
      .isLength({ max: 100 })
      .withMessage('Search term must be less than 100 characters'),
  ],
  validateRequest,
  asyncHandler(async (req, res) => {
    const { limit = 10, page = 1, search } = req.query;

    // Mock user data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply search filter if provided
    let filteredUsers = allUsers;
    if (search) {
      const searchTerm = search.toLowerCase();
      filteredUsers = allUsers.filter(user =>
        user.name.toLowerCase().includes(searchTerm) ||
        user.email.toLowerCase().includes(searchTerm)
      );
    }

    // Sanitize user data
    const sanitizedUsers = filteredUsers.map(sanitizeUser);

    // Apply pagination
    const startIndex = (page - 1) * limit;
    const paginatedUsers = sanitizedUsers.slice(startIndex, startIndex + limit);

    res.json({
      data: paginatedUsers,
      meta: {
        total: sanitizedUsers.length,
        page,
        limit,
        totalPages: Math.ceil(sanitizedUsers.length / limit),
      },
    });
  })
);

/**
 * Get user by ID endpoint
 * @route GET /users/:id
 */
app.get('/users/:id',
  asyncHandler(async (req, res, next) => {
    // Validate and sanitize ID parameter
    const userId = parseInt(req.params.id, 10);

    if (isNaN(userId) || userId <= 0) {
      return res.status(400).json({
        error: 'Invalid user ID',
        details: 'User ID must be a positive integer',
      });
    }

    // Mock user lookup
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        error: 'User not found',
        details: `No user found with ID ${userId}`,
      });
    }

    res.json({ data: sanitizeUser(user) });
  })
);

// ============================================================================
// ERROR HANDLING
// ============================================================================

/**
 * Handle 404 - Not Found errors
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    details: `Route ${req.method} ${req.path} not found`,
    path: req.path,
    method: req.method,
  });
});

/**
 * Global error handler - catches all errors
 * Must be defined last, after all routes and middleware
 */
app.use((err, req, res, next) => {
  // Log error with request context
  console.error('Error logged:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });

  // Determine status code
  const status = err.status || err.statusCode || 500;

  // Prepare error response
  const errorResponse = {
    error: err.name || 'Error',
    ...(NODE_ENV === 'development' && {
      message: err.message,
      stack: err.stack,
    }),
  };

  // In production, hide sensitive error details
  if (NODE_ENV === 'production' && status === 500) {
    errorResponse.message = 'Internal Server Error';
    delete errorResponse.stack;
  }

  res.status(status).json(errorResponse);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

// Only start server if not being imported for testing
if (require.main === module) {
  const server = app.listen(PORT, () => {
    console.log(`🚀 Server running on port ${PORT}`);
    console.log(`📝 Environment: ${NODE_ENV}`);
    console.log(`🔒 Security: Helmet, CORS, Rate Limiting enabled`);
  });

  // Graceful shutdown handler
  const gracefulShutdown = (signal) => {
    console.log(`\n${signal} received. Starting graceful shutdown...`);

    server.close(() => {
      console.log('Server closed. Process exiting.');
      process.exit(0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
      console.error('Forced shutdown after timeout');
      process.exit(1);
    }, 10000);
  };

  // Handle shutdown signals
  process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
  process.on('SIGINT', () => gracefulShutdown('SIGINT'));

  // Handle uncaught exceptions
  process.on('uncaughtException', (err) => {
    console.error('Uncaught Exception:', err);
    gracefulShutdown('uncaughtException');
  });

  // Handle unhandled promise rejections
  process.on('unhandledRejection', (reason, promise) => {
    console.error('Unhandled Rejection at:', promise, 'reason:', reason);
    gracefulShutdown('unhandledRejection');
  });
}

// Export app for testing
module.exports = app;

